.venv/Scripts/python.exe -c "
import json, subprocess
pricing = json.load(open('er005_output/cost_baseline_01/pricing_snapshot.json', encoding='utf-8'))['prices']
def price(provider, model, meter, tier='Standard'):
    for p in pricing:
        if p['provider']==provider and p['model']==model and p['meter']==meter and p.get('tier','Standard')==tier:
            return p['price']
    return None

files = [
 'er006_output/pool_pilot_01/pool_n18_notifications_specfix_v2/raw_usage_log_open107_support.jsonl',
 'er006_output/pool_pilot_01/pool_n18_notifications_specfix_v2/raw_usage_log_open108.jsonl',
 'er006_output/pool_pilot_01/pool_n18_notifications_specfix_v2/raw_usage_log_open108_support.jsonl',
 'er011_output/kp_en_asr_false_rejection_prod_wiring_01/raw_usage_log.jsonl',
 'er011_output/open111_a2_reading_trial_06/raw_usage_log_phase2.jsonl',
]
total_usd = 0.0
n = 0
for fpath in files:
    diff = subprocess.run(['git','diff','--',fpath], capture_output=True, text=True, encoding='utf-8').stdout
    for line in diff.splitlines():
        if not line.startswith('+') or line.startswith('+++'):
            continue
        try:
            r = json.loads(line[1:])
        except Exception:
            continue
        provider = r.get('provider'); model = r.get('model_id')
        it, ot = r.get('input_tokens') or 0, r.get('output_tokens') or 0
        ct = r.get('cached_input_tokens') or 0
        cost = 0.0
        try:
            if provider == 'openai':
                billable_in = max(it-ct, 0)
                cost = (billable_in/1e6)*price('openai',model,'input_tokens') + (ct/1e6)*price('openai',model,'cached_input_tokens') + (ot/1e6)*price('openai',model,'output_tokens')
            elif provider == 'openai_asr':
                cost = 0.0  # pricing lookup uncertain, treat separately
            elif provider == 'gemini':
                cost = 0.0
        except Exception as e:
            cost = 0.0
        total_usd += cost
        n += 1
print('records', n, 'openai_text_cost_usd', round(total_usd,4), 'jpy', round(total_usd*160,2))
"

